```{.r .cell-code .hidden}
# Save model objects
odds <- exp(coef(multinom1))
ci <- exp(confint(multinom1))
z_15 <- summary(multinom1)$coefficients / summary(multinom1)$standard.errors
p_15 <- (1 - pnorm(abs(z_15), 0, 1)) * 2
```
