# Create legend
legend_access <- tm_shape(phx_bg) +
  tm_polygons(fill = "white", col = "white") +
  tm_add_legend(
    title = "Tree canopy access categories",
    type = "polygons",
    fill = c("#FF0000", "#0000FF", "#f4ada8", "#a7adf9", "gray90"),
    col = c("black", "black", "black", "black"),
    labels = c("High PTCC/High PTAS", 
               "Low PTCC/Low PTAS", 
               "High PTCC/Low PTAS", 
               "Low PTCC/High PTAS",
               "No data"),
    frame = TRUE
    ) +
    tm_layout(legend.only = TRUE)

# Create map of tree canopy access categories
map_access <- tm_shape(phx_city_limits) +
  tm_polygons(fill = "gray90", 
              col = "black", 
              lwd = 1.3) +
  tm_shape(phx_bg) +
  tm_polygons(fill = "canopy_access_type_15",
              fill.scale = tm_scale_ordinal(levels = c("HH", "LL", "HL", "LH", "No data"),
                                            values = c("#FF0000", "#0000FF", "#f4ada8", "#a7adf9", "gray90"),
                                            labels = c("High PTCC/High PTAS", "Low PTCC/Low PTAS", "High PTCC/Low PTAS", "Low PTCC/High PTAS"))) +
  tm_layout(frame = FALSE, legend.show = FALSE)

# Plot map and legend
ggdraw() +
  draw_plot(tmap_grob(map_access)) +
  draw_plot(tmap_grob(legend_access), 
            x = 0.06, 
            y = 0.55, 
            width = 0.3, 
            height = 0.35)
